// Expand compact format into readable form
export function expand(w) {
  const out = { id: w.i, num: w.n, category: w.c, type: w.t };
  if (w.t === "strength_split") {
    out.groups = (w.g || []).map(g => ({
      label: g.l, sets: g.s, exercise: g.e,
      movement: g.m, mode: g.q, video: g.v, reps: g.r,
    }));
  } else if (w.t === "strength_total_body") {
    out.template = w.tp;
    out.pattern1 = (w.p1 || []).map(r => ({
      track: r.k, exercise: r.e, movement: r.m, video: r.v, reps: r.r,
    }));
    out.pattern2 = (w.p2 || []).map(r => ({
      track: r.k, exercise: r.e, movement: r.m, video: r.v, reps: r.r,
    }));
    out.pattern3 = (w.p3 || []).map(r => ({
      track: r.k, exercise: r.e, movement: r.m, video: r.v, reps: r.r,
    }));
  } else if (w.t === "cardio_12") {
    out.exercises = (w.x || []).map(e => ({
      exercise: e.e, movement: e.m, video: e.v,
    }));
  } else if (w.t === "cardio_4group") {
    out.groups = {};
    for (const k of ["A","B","C","D"]) {
      out.groups[k] = ((w.G || {})[k] || []).map(it => ({
        exercise: it.e, equipment: it.q, video: it.v,
      }));
    }
  }
  out.abs = (w.A || []).map(a => ({ exercise: a.e, video: a.v, reps: a.r }));
  out.finisher = (w.F || []).map(a => ({ exercise: a.e, video: a.v, reps: a.r }));
  out.steady = (w.S || []).map(a => ({ exercise: a.e, video: a.v, reps: a.r }));
  return out;
}

export const WORKOUTS = RAW.map(expand);
export const BY_ID = Object.fromEntries(WORKOUTS.map(w => [w.id, w]));
export const BY_CATEGORY = WORKOUTS.reduce((acc, w) => {
  (acc[w.category] = acc[w.category] || []).push(w);
  return acc;
}, {});

// Sort each category by num
Object.values(BY_CATEGORY).forEach(arr => arr.sort((a, b) => a.num - b.num));

