// ============================================================
// HELPERS
// ============================================================

export function getCurrentDay() {
  const d = new Date().getDay(); // 0=Sun, 1=Mon, ...
  return d === 0 ? 6 : d - 1; // Mon=0, Sun=6
}

export function getCurrentMondayISO() {
  const d = new Date();
  const day = d.getDay();
  const offset = day === 0 ? 6 : day - 1;
  d.setDate(d.getDate() - offset);
  d.setHours(0, 0, 0, 0);
  return d.toISOString().slice(0, 10);
}

export function flipWeek(w) { return w === "A" ? "B" : "A"; }

export function safeUid(prefix) {
  return `${prefix}_${Date.now()}_${Math.random().toString(16).slice(2, 8)}`;
}

export function daysAgo(ts) {
  const days = Math.floor((Date.now() - ts) / 86400000);
  if (days === 0) return "today";
  if (days === 1) return "1d";
  if (days < 7) return `${days}d`;
  if (days < 30) return `${Math.floor(days/7)}w`;
  return `${Math.floor(days/30)}mo`;
}

export function previewLine(w) {
  if (w.type === "strength_split") {
    const exs = w.groups.map(g => g.exercise.split("—")[0].trim()).slice(0, 3);
    return exs.join(" · ");
  }
  if (w.type === "strength_total_body") {
    const exs = w.pattern1.map(r => r.exercise.split("—")[0].trim()).slice(0, 3);
    return `${w.template || ""}${exs.length ? " · " + exs.join(" · ") : ""}`;
  }
  if (w.type === "cardio_12") {
    return `30 on / 10 off · ${w.exercises.length} movements`;
  }
  if (w.type === "cardio_4group") {
    const totalEx = Object.values(w.groups).reduce((s, g) => s + g.length, 0);
    return `4 groups · ${totalEx} exercises · 30/10`;
  }
  return "";
}
export function collectKeys(w) {
  const keys = [];
  if (w.type === "strength_split") {
    w.groups.forEach((_, i) => keys.push(`g${i}`));
  } else if (w.type === "strength_total_body") {
    w.pattern1.forEach((_, i) => keys.push(`p1_${i}`));
    w.pattern2.forEach((_, i) => keys.push(`p2_${i}`));
    w.pattern3.forEach((_, i) => keys.push(`p3_${i}`));
  } else if (w.type === "cardio_12") {
    w.exercises.forEach((_, i) => keys.push(`x_${i}`));
  } else if (w.type === "cardio_4group") {
    for (const k of ["A","B","C","D"]) {
      w.groups[k].forEach((_, i) => keys.push(`G${k}_${i}`));
    }
  }
  w.abs.forEach((_, i) => keys.push(`A_${i}`));
  w.finisher.forEach((_, i) => keys.push(`F_${i}`));
  w.steady.forEach((_, i) => keys.push(`S_${i}`));
  return keys;
}
